import * as U from '../ui.js';
import {getAppointments} from '../appointments.js';
U.mount(()=>{const appointments=getAppointments().sort((a,b)=>a.planned_start_at.localeCompare(b.planned_start_at));return U.heading('A little help, right on time','My appointments.','A clear view of the conversations you’ve planned.','<a class="btn teal" href="book-appointment.html">'+U.icon('plus')+' Book now</a>')+(appointments.length?`<div class="appointment-count"><span>${U.tag(appointments.length+' appointment'+(appointments.length===1?'':'s'),'teal-tag')}</span><p class="small muted">Times shown in ${U.esc(U.db.users[0].timezone)}</p></div><div class="grid2">${appointments.map(a=>`<article class="card appointment-card"><div class="section-head"><div class="support-symbol">${U.icon('calendar')}</div>${U.tag('Booked','teal-tag')}</div><h2>${U.esc(a.title)}</h2><div class="appointment-detail">${U.icon('calendar')}<span>${U.date(U.day(a.planned_start_at),{weekday:'long',month:'long',day:'numeric',year:'numeric'})}</span></div><div class="appointment-detail">${U.icon('clock')}<span>${U.time(a.planned_start_at)} · ${U.esc(U.db.users[0].timezone)}</span></div><div class="appointment-person"><strong>${U.esc(a.full_name)}</strong><span>${U.esc(a.contact_email)}</span></div>${a.description?`<p class="appointment-notes">${U.esc(a.description)}</p>`:''}</article>`).join('')}</div><div class="note" style="margin-top:22px">${U.icon('info')}<span>These bookings are saved to your signed-in account. No real appointments or emails have been sent.</span></div>`:`<section class="card appointments-empty"><div class="empty-calendar">${U.icon('calendar')}<span>+</span></div><div class="eyebrow">A LITTLE SPACE IN YOUR CALENDAR</div><h2>No appointments yet.</h2><p>When you book an appointment, you’ll find its details here.<br>Start with a little support for whatever comes next.</p><a class="btn teal" href="book-appointment.html">Book now ${U.icon('arrow')}</a><a class="text-link" href="index.html">Back to Today →</a></section>`)});
